import translations from '/assets/js/languages/translations.js';
import { translate } from '/assets/js/languages/translate.js';

/*
 * Two modes:
 * - URL mode (home page): each language has its own URL (/ and /es/, generated by
 *   scripts/build-i18n.mjs). The page language is <html lang>; the toggle
 *   navigates to the other version and remembers the choice.
 * - In-place mode (pages without hreflang alternates, e.g. resume): texts are
 *   swapped in the DOM.
 * Both use the same markup: data-i18n="key" and data-i18n-attr="attr:key;...".
 */

const STORAGE_KEY = 'lang';
const SUPPORTED = ['en', 'es'];

const getStoredLanguage = () => {
  try {
    const lang = localStorage.getItem(STORAGE_KEY);
    return SUPPORTED.includes(lang) ? lang : null;
  } catch {
    return null;
  }
};

const storeLanguage = (lang) => {
  try {
    localStorage.setItem(STORAGE_KEY, lang);
  } catch {
    /* private mode / blocked storage: preference just isn't remembered */
  }
};

// CV: el enlace trae el idioma de la página de origen (?lang=es). Gana sobre
// lo guardado, se guarda como la elección actual y se quita de la URL
const languageFromUrl = () => {
  const url = new URL(location.href);
  const lang = url.searchParams.get('lang');
  if (!SUPPORTED.includes(lang)) return null;
  storeLanguage(lang);
  url.searchParams.delete('lang');
  history.replaceState(history.state, '', url.pathname + url.search + url.hash);
  return lang;
};

const detectBrowserLanguage = () => {
  const languages = navigator.languages || [navigator.language || ''];
  return languages.some((l) => /^es\b/i.test(l)) ? 'es' : 'en';
};

const t = (key, lang) => {
  const value = translate(translations, key, lang);
  return typeof value === 'string' ? value : translate(translations, key, 'en');
};

let currentLanguage = 'en';

export const getValidationMessages = () => translations.validation[currentLanguage];

// *texto* en una traducción → <strong>texto</strong> (sin HTML arbitrario)
const setRichText = (el, value) => {
  el.textContent = '';
  value.split(/(\*[^*]+\*)/).forEach((part) => {
    if (!part) return;
    if (part.startsWith('*') && part.endsWith('*') && part.length > 2) {
      const strong = document.createElement('strong');
      strong.textContent = part.slice(1, -1);
      el.append(strong);
    } else {
      el.append(part);
    }
  });
};

const applyTranslations = (lang) => {
  document.querySelectorAll('[data-i18n]').forEach((el) => {
    const value = t(el.dataset.i18n, lang);
    if (typeof value === 'string') setRichText(el, value);
  });

  document.querySelectorAll('[data-i18n-attr]').forEach((el) => {
    el.dataset.i18nAttr.split(';').forEach((pair) => {
      const [attr, key] = pair.split(':').map((s) => s.trim());
      const value = t(key, lang);
      if (typeof value === 'string') el.setAttribute(attr, value);
    });
  });
};

// Desktop (≥600px): the About section is hidden and its text is appended to
// the home description.
const handleResponsiveContent = (lang) => {
  const homeDescription = document.querySelector('.home__description');
  if (!homeDescription) return;

  const homeText = t('homeDescription', lang);
  const lines = translate(translations, 'heroLines', lang);
  if (window.innerWidth >= 600 && Array.isArray(lines)) {
    // Escritorio: la presentación, una línea de espacio y luego 7 líneas
    // de 7 palabras, una por renglón
    homeDescription.textContent = '';
    homeDescription.classList.add('home__description--lines');
    const intro = document.createElement('span');
    intro.className = 'home__intro';
    setRichText(intro, homeText);
    homeDescription.append(
      intro,
      ...lines.map((line) => {
        const span = document.createElement('span');
        span.className = 'home__line';
        span.textContent = line;
        return span;
      }),
    );
  } else {
    homeDescription.classList.remove('home__description--lines');
    setRichText(homeDescription, homeText);
  }
};

const setLanguage = (lang) => {
  currentLanguage = lang;
  document.documentElement.lang = lang; // screen readers and search engines

  applyTranslations(lang);
  handleResponsiveContent(lang);

  window.dispatchEvent(
    new CustomEvent('languageChange', {
      detail: { language: lang, validationMessages: translations.validation?.[lang] ?? null },
    }),
  );
};

// Tras un cambio de idioma, vuelve a la sección en la que estaba el visitante.
// En una página prerenderizada se espera a que se active (se muestre).
const restorePendingHash = () => {
  const run = () => {
    let hash = null;
    try {
      hash = sessionStorage.getItem('aq-hash');
      sessionStorage.removeItem('aq-hash');
    } catch {
      return;
    }
    if (!hash) return;
    history.replaceState(null, '', hash);
    document.querySelector(hash)?.scrollIntoView({ behavior: 'instant' });
  };
  if (document.prerendering) {
    document.addEventListener('prerenderingchange', run, { once: true });
  } else {
    run();
  }
};

// Prerenderiza la página en el otro idioma cuando hay intención de cambiar
// (cursor encima, foco con teclado o dedo en el botón), no en cada visita:
// casi nadie cambia de idioma y construir la otra página cuesta datos y CPU.
// El cambio sigue siendo casi instantáneo. Solo navegadores con speculation rules.
const prerenderOnIntent = (toggle, alternates, targetLang) => {
  if (!HTMLScriptElement.supports?.('speculationrules')) return;
  const target = [...alternates].find((l) => l.hreflang === targetLang);
  if (!target) return;
  const { pathname } = new URL(target.href, location.href);
  const area = toggle.closest('.navbar__toggle--language') || toggle;

  const events = ['pointerenter', 'focusin', 'touchstart'];
  const prerender = () => {
    events.forEach((type) => area.removeEventListener(type, prerender));
    const rules = document.createElement('script');
    rules.type = 'speculationrules';
    rules.textContent = JSON.stringify({ prerender: [{ urls: [pathname] }] });
    document.head.append(rules);
  };
  events.forEach((type) => area.addEventListener(type, prerender, { passive: true }));
};

const switchLanguages = () => {
  restorePendingHash();
  const languageToggle = document.getElementById('language-toggle');
  const alternates = document.querySelectorAll('link[rel="alternate"][hreflang]');
  const urlMode = alternates.length > 0;

  const initialLang = urlMode
    ? SUPPORTED.includes(document.documentElement.lang)
      ? document.documentElement.lang
      : 'en'
    : languageFromUrl() || getStoredLanguage() || detectBrowserLanguage();

  setLanguage(initialLang);

  if (languageToggle) {
    languageToggle.checked = initialLang === 'es';

    if (urlMode) prerenderOnIntent(languageToggle, alternates, initialLang === 'es' ? 'en' : 'es');

    languageToggle.addEventListener('change', () => {
      const lang = languageToggle.checked ? 'es' : 'en';

      // Animación de clic: se fija la bandera del idioma destino (la misma que
      // mostró el hover) y rebota, sin volver a girar
      const wrapper = languageToggle.closest('.navbar__toggle--language');
      if (wrapper) {
        wrapper.querySelectorAll('img').forEach((img) => {
          const isTarget = img.classList.contains(`navbar__toggle--language-${lang}`);
          img.classList.toggle('is-target', isTarget);
          img.classList.toggle('is-current', !isTarget);
        });
        wrapper.classList.add('is-switching');
      }
      storeLanguage(lang);

      if (urlMode) {
        const target = [...alternates].find((l) => l.hreflang === lang);
        if (target) {
          const url = new URL(target.href, location.href);
          // Se navega a la URL exacta que está prerenderizada (sin #sección),
          // y la sección se restaura al activarse (restorePendingHash)
          try {
            if (location.hash) sessionStorage.setItem('aq-hash', location.hash);
          } catch {
            /* sin almacenamiento: solo se pierde la sección */
          }
          // Deja ver el rebote de la bandera antes de cambiar de página
          setTimeout(() => location.assign(url.pathname), 220);
          return;
        }
      }
      setLanguage(lang);
      // Cambio en la misma página (resume): termina la animación y limpia
      setTimeout(() => {
        wrapper?.classList.remove('is-switching');
        wrapper?.querySelectorAll('img').forEach((img) => img.classList.remove('is-target', 'is-current'));
      }, 500);
    });
  }

  window.addEventListener('resize', () => handleResponsiveContent(currentLanguage));
};

export default switchLanguages;
